//
// Oklahoma income tax withholding: Packet OW-2 (Revised 11-2025), "2026
// Oklahoma Income Tax Withholding Tables", Percentage Formula Method:
//   1. allowance amount for the payroll frequency x allowances (OK-W-4)
//   2. subtract from the period's wages
//   3. apply the period's percentage table (single or married)
//   round to the nearest whole dollar ($2.49 -> $2.00, $2.50 -> $3.00)
// The per-period tables below are generated by tools/state/generate_ok.py
// from the OW-2 packet. The packet's worked example ($1,825 semimonthly,
// married, 2 allowances -> $37.00) is in the tests.
//
// OK-W-4 input: { filingStatus: "single" | "married" |
//   "marriedWithholdAtSingle", allowances, additionalWithholdingCents?,
//   exempt? }  ("Married, but withhold at higher Single rate" uses the
//   single table).
// No OK-W-4 on file: "withhold tax as if the employee were a single person
// who has claimed no withholding allowances" (OAC 710:90-3-3(f)).
//
// Wages: federal income-tax wages. Oklahoma income starts from federal
// adjusted gross income, which excludes pre-tax 401(k) deferrals; the OW-2
// packet doesn't address 401(k) directly.

const { formChecker, onFile, PERIOD_BY_COUNT } = require("./formUtil");
const { fromBaseTable } = require("./brackets");

// Allowance amount per payroll frequency (OW-2, "Table of Withholding
// Allowance Amounts"): the $1,000 personal exemption / periods.
const ALLOWANCE_CENTS = Object.freeze({
  daily: 3_85,
  weekly: 19_23,
  biweekly: 38_46,
  semimonthly: 41_67,
  monthly: 83_33,
  quarterly: 250_00,
  semiannual: 500_00,
  annual: 1_000_00,
});

// Generated by tools/state/generate_ok.py from Packet OW-2 (Revised 11-2025).
// Rows: [overCents, baseCents, rateBasisPoints].
const PERCENTAGE_TABLES = Object.freeze({
    daily: Object.freeze({
      single: Object.freeze([[0, 0, 0], [3900, 0, 250], [4300, 11, 350], [5200, 42, 450]]),
      married: Object.freeze([[0, 0, 0], [7800, 0, 250], [8700, 22, 350], [10400, 84, 450]]),
    }),
    weekly: Object.freeze({
      single: Object.freeze([[0, 0, 0], [19400, 0, 250], [21600, 55, 350], [26100, 210, 450]]),
      married: Object.freeze([[0, 0, 0], [38800, 0, 250], [43300, 111, 350], [52100, 420, 450]]),
    }),
    biweekly: Object.freeze({
      single: Object.freeze([[0, 0, 0], [38800, 0, 250], [43300, 111, 350], [52100, 420, 450]]),
      married: Object.freeze([[0, 0, 0], [77700, 0, 250], [86500, 221, 350], [104200, 840, 450]]),
    }),
    semimonthly: Object.freeze({
      single: Object.freeze([[0, 0, 0], [42100, 0, 250], [46900, 120, 350], [56500, 455, 450]]),
      married: Object.freeze([[0, 0, 0], [84200, 0, 250], [93800, 240, 350], [112900, 910, 450]]),
    }),
    monthly: Object.freeze({
      single: Object.freeze([[0, 0, 0], [84200, 0, 250], [93800, 240, 350], [112900, 910, 450]]),
      married: Object.freeze([[0, 0, 0], [168300, 0, 250], [187500, 479, 350], [225800, 1821, 450]]),
    }),
    quarterly: Object.freeze({
      single: Object.freeze([[0, 0, 0], [252500, 0, 250], [281300, 719, 350], [338800, 2731, 450]]),
      married: Object.freeze([[0, 0, 0], [505000, 0, 250], [562500, 1438, 350], [677500, 5463, 450]]),
    }),
    semiannual: Object.freeze({
      single: Object.freeze([[0, 0, 0], [505000, 0, 250], [562500, 1438, 350], [677500, 5463, 450]]),
      married: Object.freeze([[0, 0, 0], [1010000, 0, 250], [1125000, 2875, 350], [1355000, 10925, 450]]),
    }),
    annual: Object.freeze({
      single: Object.freeze([[0, 0, 0], [1010000, 0, 250], [1125000, 2875, 350], [1355000, 10925, 450]]),
      married: Object.freeze([[0, 0, 0], [2020000, 0, 250], [2250000, 5750, 350], [2710000, 21850, 450]]),
    }),
});

const TABLES = Object.freeze({
  2026: Object.freeze({
    allowanceCents: ALLOWANCE_CENTS,
    percentageTables: PERCENTAGE_TABLES,
    sources: Object.freeze([
      "Oklahoma Tax Commission, Packet OW-2 2026 Oklahoma Income Tax Withholding Tables (Revised 11-2025): https://oklahoma.gov/content/dam/ok/en/tax/documents/resources/publications/businesses/withholding-tables/WHTables-2026.pdf",
      "Oklahoma Tax Commission, OAC 710:90 Withholding (2026): https://oklahoma.gov/content/dam/ok/en/tax/documents/resources/rules-and-policies/agency-rules/2026/Chapter90-Withholding-2026.pdf",
    ]),
  }),
});

function validateForm(form) {
  if (!onFile(form)) return;
  const c = formChecker("Oklahoma OK-W-4");
  c.bool(form, "exempt");
  if (form.exempt) return;
  c.oneOf(form, "filingStatus", ["single", "married", "marriedWithholdAtSingle"]);
  c.nonNegInt(form, "allowances");
  c.cents(form, "additionalWithholdingCents");
}

function compute({ taxYear, wagesCents, payPeriodsPerYear, form }) {
  const t = TABLES[taxYear];
  validateForm(form);
  const period = PERIOD_BY_COUNT[payPeriodsPerYear];
  if (!period) throw new Error(`Oklahoma has no percentage table for ${payPeriodsPerYear} pay periods a year`);
  const has = onFile(form);
  if (has && form.exempt) return { stateCents: 0, formBasis: "ok-w-4-exempt", lines: {} };
  const status = has && form.filingStatus === "married" ? "married" : "single";
  const allowances = has ? form.allowances ?? 0 : 0;
  const net = Math.max(0, wagesCents - allowances * t.allowanceCents[period]);
  const tax = fromBaseTable(net, t.percentageTables[period][status]);
  const extra = has ? form.additionalWithholdingCents ?? 0 : 0;
  return {
    stateCents: Math.round(tax / 100) * 100 + extra,
    formBasis: has ? "ok-w-4" : "none-on-file-single-zero",
    lines: { period, status, netCents: net, taxCents: tax },
  };
}

module.exports = {
  code: "OK",
  name: "Oklahoma",
  wageBasis: "federal-income-tax-wages",
  years: Object.keys(TABLES).map(Number),
  TABLES,
  validateForm,
  compute,
};
